"""Exercise proof admission with generated bytes; no provider/network transport exists."""
from dataclasses import replace
import copy
import json
import importlib.util
import os
from pathlib import Path
import sys
import tempfile
import unittest
from unittest.mock import patch

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from scripts.attachments_proof.generate import generate_fixture_set
from scripts.attachments_proof.harness import (
    OfflineProofHarness, ProofFile, ProofRequest, MODEL, BILLING,
    load_pricing_snapshot, synthetic_bound,
)


@unittest.skipUnless(os.name == "posix" and importlib.util.find_spec("PIL") is not None,
                     "Offline generator requires local Pillow and POSIX no-follow support; no dependencies downloaded")
class GeneratedAdmissionTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix='watch-attachment-offline-')
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name).resolve() / 'fictional-set'
        # Guard the complete generation + harness execution, not just the transport stub.
        self.addCleanup(patch.stopall)
        patch('socket.socket', side_effect=AssertionError('Network forbidden')).start()
        patch('socket.create_connection', side_effect=AssertionError('Network forbidden')).start()
        self.manifest = generate_fixture_set(self.root)
        self.rows = {row['name']: row for row in self.manifest['files']}
        self.folder = self.root / 'scratch-a'
        self.folder.mkdir()
        self.other = self.root / 'scratch-b'
        self.other.mkdir()
        self.harness = OfflineProofHarness(self.root, pricing=load_pricing_snapshot())

    def request(self, name='requirements.txt', **changes):
        row = self.rows[name]
        body = {'model': MODEL, 'max_tokens': 1024,
                'system': 'Fictional analysis only. No tools.',
                'messages': [{'role': 'user', 'content': 'Summarize the fictional attachment.'}]}
        request = ProofRequest(slot='O1', body=body, input_bound=synthetic_bound(body),
            billing=copy.deepcopy(BILLING), expected_folder=self.folder, actual_folder=self.folder,
            files=(ProofFile(self.root / row['path'], row['sha256'], row['mediaType']),))
        return replace(request, **changes)

    def rejected_without_stub(self, request):
        with self.assertRaises((ValueError, RuntimeError)):
            self.harness.run(request)
        self.assertEqual(self.harness.summary()['stub_attempts'], 0)

    def test_generated_locked_pdf_rejected_before_stub(self):
        raw = (self.root / self.rows['locked-delivery.pdf']['path']).read_bytes()
        self.assertIn(b'/Encrypt', raw)
        self.rejected_without_stub(self.request('locked-delivery.pdf'))

    def test_generated_oversized_encoded_input_rejected_without_truncation(self):
        text = (self.root / self.rows['over-budget.txt']['path']).read_text()
        request = self.request('over-budget.txt')
        body = copy.deepcopy(request.body)
        body['messages'][0]['content'] = text
        self.assertGreater(len(json.dumps(body).encode()), 524288)
        self.rejected_without_stub(replace(request, body=body, input_bound=synthetic_bound(body)))
        self.assertEqual((self.root / self.rows['over-budget.txt']['path']).read_text(), text)

    def test_wrong_scratch_folder_rejected_without_claiming_native_mapping_proof(self):
        self.rejected_without_stub(self.request(actual_folder=self.other))

    def test_unsupported_recipient_and_type_rejected_before_stub(self):
        self.rejected_without_stub(self.request(recipient='unsupported'))
        req = self.request()
        self.rejected_without_stub(replace(req, files=(replace(req.files[0], media_type='application/zip'),)))

    def test_explicit_forwarding_intent_rejected_not_a_natural_language_classifier(self):
        self.rejected_without_stub(self.request(intent='forward'))

    def test_modified_generated_file_fails_pinned_hash(self):
        req = self.request()
        req.files[0].path.chmod(0o600)
        req.files[0].path.write_text('changed fictional bytes')
        self.rejected_without_stub(req)

    def test_generated_file_lost_result_keeps_one_stub_attempt_across_restart(self):
        request = self.request()
        result = self.harness.run(request, fault='lost_result')
        self.assertEqual(result['state'], 'unknown')
        reopened = OfflineProofHarness(self.root, pricing=load_pricing_snapshot())
        self.assertEqual(reopened.run(request), result)
        with self.assertRaises((ValueError, RuntimeError)):
            reopened.run(replace(request, slot='O2'))
        self.assertEqual(reopened.summary()['stub_attempts'], 1)
        self.assertEqual(reopened.summary()['network_transmissions'], 0)

    def test_missing_and_mismatched_bound_reject_with_generated_files(self):
        req = self.request()
        self.rejected_without_stub(replace(req, input_bound=None))
        changed = copy.deepcopy(req.body)
        changed['messages'][0]['content'] += ' changed'
        self.rejected_without_stub(replace(req, body=changed))


if __name__ == '__main__':
    unittest.main()
